EVIDENCE_CONTRACT = "domainry-backend-acceptance-evidence-v1"
ARTIFACT_CONTRACT = "domainry-backend-acceptance-artifact-v1"
RUN_REPORT_CONTRACT = "domainry-backend-acceptance-run-v2"
STALE_REPORT_CONTRACT = "domainry-backend-acceptance-stale-report-v1"
PRODUCER = "domainry-runtime-acceptance-harness"
PRINCIPAL_CONTEXT_CONTRACT = "domainry-principal-context-v1"
ACCEPTANCE_SECRETS_CONTRACT = "domainry-acceptance-secrets-v1"

DENOMINATOR_RELATIVE = ".domainry/builder/acceptance/denominator.json"
RUNTIME_STATE_RELATIVE = ".domainry/builder/runtime/runtime-process.json"
SECRETS_RELATIVE = ".domainry/builder/runtime/acceptance-secrets.json"
