CAPTURED_FROM = {
    "http_exchange": ["runtime_http"], "sse_transcript": ["runtime_http"], "durable_refetch": ["runtime_http"],
    "runtime_restart": ["runtime_process"], "worker_terminal": ["runtime_worker"],
