    "transaction_trace": ["runtime_database"], "security_posture": ["runtime_database"],
    "differentiated_scope_data": ["runtime_http", "runtime_database"], "pagination_trace": ["runtime_http", "runtime_database"],
    "query_profile": ["runtime_database", "runtime_metrics"], "audit_correlation": ["runtime_database", "runtime_logs"],
    "provider_receipt": ["provider_api"],
