// This file is initial project-owned business source. Domainry will never overwrite it.
package crm

import (
	"context"
	"strings"
	"time"

	"github.com/domainry-evals/m1-crm/generated/capabilities"
	"github.com/domainry-evals/m1-crm/generated/data"
	"github.com/domainry-evals/m1-crm/generated/schema"
)

const approveConversionSurface = "business_workspace"

// ApproveConversion implements the project-owned conversion_approval.approve_conversion Handler.
func ApproveConversion(ctx context.Context, caps capabilities.ApproveConversionCapabilities, input capabilities.ApproveConversionInput) (capabilities.ApproveConversionOutput, error) {
	if strings.TrimSpace(input.RequestID) == "" {
		return capabilities.ApproveConversionOutput{}, approveConversionError("invalid_input", "request_id is required")
	}
	if caps.Execution == nil || caps.ConversionApproval == nil || caps.Customer == nil || caps.Lead == nil || caps.Notifications == nil {
		return capabilities.ApproveConversionOutput{}, approveConversionError("capability_unavailable", "required Action capability is unavailable")
	}

	principal := caps.Execution.Principal()
	if !principal.Known || principal.UserID == "" || principal.RoleKey != "sales_director" {
		return capabilities.ApproveConversionOutput{}, approveConversionError("principal_invalid", "a known sales director principal is required")
	}
	approvalID := caps.Execution.TargetID()
	if approvalID == "" {
		return capabilities.ApproveConversionOutput{}, approveConversionError("invalid_target", "approval target is required")
	}

	approval, err := caps.ConversionApproval.GetForUpdate(ctx, approvalID)
	if err != nil {
		return capabilities.ApproveConversionOutput{}, err
	}
	if approval.ID != approvalID || approval.UpdatedAt == "" || approval.LeadID.IsZero() || approval.RequesterID == "" {
		return capabilities.ApproveConversionOutput{}, approveConversionError("record_invalid", "approval record is incomplete")
	}
	if approval.Status != schema.ConversionApprovalStatusPending {
		return capabilities.ApproveConversionOutput{}, approveConversionError("invalid_state", "only a pending approval can be approved")
	}

	leadID := approval.LeadID.ID()
	lead, err := caps.Lead.GetForUpdate(ctx, leadID)
	if err != nil {
		return capabilities.ApproveConversionOutput{}, err
	}
	if lead.ID != leadID || lead.UpdatedAt == "" || lead.CompanyName == "" || lead.OwnerID == "" {
		return capabilities.ApproveConversionOutput{}, approveConversionError("record_invalid", "lead record is incomplete")
	}
	if lead.Status != schema.LeadStatusQualified {
		return capabilities.ApproveConversionOutput{}, approveConversionError("invalid_state", "approval lead must remain qualified until decision")
	}

	customerExists, err := caps.Customer.Exists(ctx, data.NewCustomerQuery().WhereSourceLeadIDEqual(schema.NewCustomerSourceLeadIDReference(leadID)))
	if err != nil {
		return capabilities.ApproveConversionOutput{}, err
	}
	if customerExists {
		return capabilities.ApproveConversionOutput{}, approveConversionError("customer_exists", "lead already has a customer")
	}

	decidedAt := time.Now().UTC()
	updatedApproval, err := caps.ConversionApproval.ConditionalUpdate(ctx,
		data.NewConversionApprovalUpdate(approvalID).
			SetStatus(schema.ConversionApprovalStatusApproved).
			SetApproverID(principal.UserID).
			SetDecidedAt(decidedAt).
			ClearRejectionReason().
			RequireStatusEqual(schema.ConversionApprovalStatusPending, capabilities.ApproveConversionActionKey+".stale_revision").
			WithExpectedUpdatedAt(approval.UpdatedAt),
	)
	if err != nil {
		return capabilities.ApproveConversionOutput{}, err
	}
	updatedLead, err := caps.Lead.ConditionalUpdate(ctx,
		data.NewLeadUpdate(leadID).
			SetStatus(schema.LeadStatusConverted).
			SetStatusChangedAt(decidedAt).
			RequireStatusEqual(schema.LeadStatusQualified, capabilities.ApproveConversionActionKey+".stale_revision").
			WithExpectedUpdatedAt(lead.UpdatedAt),
	)
	if err != nil {
		return capabilities.ApproveConversionOutput{}, err
	}

	var source *schema.CustomerSource
	if lead.Source != nil {
		value := schema.CustomerSource(*lead.Source)
		source = &value
	}
	customer, err := caps.Customer.Create(ctx, schema.CreateCustomer{
		CompanyName:    lead.CompanyName,
		ContactName:    lead.ContactName,
		ExpectedAmount: schema.CustomerExpectedAmount(approval.SubmittedAmount),
		Source:         source,
		SourceLeadID:   schema.NewCustomerSourceLeadIDReference(leadID),
		SourceOwnerID:  lead.OwnerID,
	})
	if err != nil {
		return capabilities.ApproveConversionOutput{}, err
	}
	if customer.ID == "" || updatedApproval.ID != approvalID || updatedApproval.UpdatedAt == "" || updatedLead.ID != leadID || updatedLead.Status != schema.LeadStatusConverted {
		return capabilities.ApproveConversionOutput{}, approveConversionError("mutation_invalid", "Action mutation returned an incomplete result")
	}

	companyName := lead.CompanyName
	_, err = caps.Notifications.Dispatch(ctx, capabilities.ApproveConversionNotificationIntent{
		EventType:        "crm.conversion_approved",
		SourceEventID:    input.RequestID,
		RecipientUserIDs: []string{approval.RequesterID},
		Surface:          approveConversionSurface,
		SubjectObjectKey: "conversion_approval",
		SubjectRecordID:  string(approvalID),
		SubjectVersion:   updatedApproval.UpdatedAt,
		DedupeKey:        "conversion_approval:" + string(approvalID) + ":approved",
		GroupKey:         "conversion_approval:" + string(approvalID),
		OccurredAt:       decidedAt,
		Variables: []capabilities.ApproveConversionNotificationVariable{
			{Key: "company_name", StringValue: &companyName},
		},
	})
	if err != nil {
		return capabilities.ApproveConversionOutput{}, err
	}

	return capabilities.ApproveConversionOutput{ApprovalID: approvalID, CustomerID: customer.ID, LeadID: leadID}, nil
}

func approveConversionError(suffix, message string) error {
	return &capabilities.BusinessError{Code: capabilities.ApproveConversionActionKey + "." + suffix, Message: message}
