func TestApproveConversionCreatesCustomerAndStagesDecision(t *testing.T) {
	source := schema.LeadSourceWebsite
	contact := "Ada"
	approvalCapability := &approveConversionApprovalStub{
		record: schema.ConversionApproval{
			ID:              "approval-1",
			UpdatedAt:       "approval-rev-1",
			LeadID:          schema.NewConversionApprovalLeadIDReference("lead-1"),
			RequesterID:     "rep-1",
			Status:          schema.ConversionApprovalStatusPending,
			SubmittedAmount: "125000.00",
			ThresholdAmount: "100000.00",
		},
		updateResult: schema.ConversionApproval{ID: "approval-1", UpdatedAt: "approval-rev-2", Status: schema.ConversionApprovalStatusApproved},
	}
	leadCapability := &approveConversionLeadStub{
		record:       schema.Lead{ID: "lead-1", UpdatedAt: "lead-rev-1", CompanyName: "Acme", ContactName: &contact, ExpectedAmount: amount("125000.00"), OwnerID: "rep-1", Source: &source, Status: schema.LeadStatusQualified},
		updateResult: schema.Lead{ID: "lead-1", UpdatedAt: "lead-rev-2", Status: schema.LeadStatusConverted},
	}
	customerCapability := &approveConversionCustomerStub{}
	notificationCapability := &approveConversionNotificationStub{}

	output, err := ApproveConversion(t.Context(), capabilities.ApproveConversionCapabilities{
		Execution:          approveConversionExecutionStub{principal: capabilities.Principal{Known: true, UserID: "director-1", RoleKey: "sales_director"}, targetID: "approval-1"},
		ConversionApproval: approvalCapability,
		Customer:           customerCapability,
		Lead:               leadCapability,
		Notifications:      notificationCapability,
	}, capabilities.ApproveConversionInput{RequestID: "workflow-1"})
	if err != nil {
		t.Fatalf("ApproveConversion returned error: %v", err)
	}
	if output.ApprovalID != "approval-1" || output.LeadID != "lead-1" || output.CustomerID != "customer-1" {
		t.Fatalf("unexpected output: %+v", output)
	}
	if approvalCapability.updateCalls != 1 || leadCapability.updateCalls != 1 || customerCapability.createCalls != 1 {
		t.Fatalf("unexpected mutation counts: approval=%d lead=%d customer=%d", approvalCapability.updateCalls, leadCapability.updateCalls, customerCapability.createCalls)
	}
	if customerCapability.created.CompanyName != "Acme" || customerCapability.created.ExpectedAmount != "125000.00" || customerCapability.created.SourceLeadID.ID() != "lead-1" || customerCapability.created.SourceOwnerID != "rep-1" {
		t.Fatalf("customer did not preserve conversion facts: %+v", customerCapability.created)
	}
	if len(notificationCapability.intents) != 1 {
		t.Fatalf("expected one notification, got %d", len(notificationCapability.intents))
	}
	intent := notificationCapability.intents[0]
	if intent.EventType != "crm.conversion_approved" || intent.SourceEventID != "workflow-1" || intent.Surface != approveConversionSurface || len(intent.RecipientUserIDs) != 1 || intent.RecipientUserIDs[0] != "rep-1" || intent.SubjectVersion != "approval-rev-2" || intent.OccurredAt.IsZero() {
		t.Fatalf("unexpected notification intent: %+v", intent)
	}
}

